bucket = hash & ckh->n_entries_mask;
if (ckh->tab == nullptr || ckh->n_entries == 0) {
    return SIZE_MAX;
}

while (true) {
    if (ckh->tab[bucket * 2] == nullptr) {
        return bucket;
    }

    if (ckh->tab[bucket * 2] == key || (ckh->key_comp(ckh->tab[bucket * 2], key) == 0)) {
        return bucket;
    }

    hash = hash_combine(hash, 1);
    bucket = hash & ckh->n_entries_mask;

    if (bucket == (hash & ckh->n_entries_mask)) {
        return bucket;
    }
}
